package com.example.rokidgeminisecretary;
import android.content.*;import android.location.Location;import org.json.*;import java.lang.reflect.*;import java.util.*;
/** Public-free synthetic trip traces; actual APK HUD method and glasses packet formatter. */
public final class NavigationModeMatrixChecks {
 static JSONArray cases;static String mode;static void check(String label,boolean pass)throws Exception{cases.put(new JSONObject().put("mode",mode).put("scenario",label).put("pass",pass));}
 static JSONObject hud(MainActivity owner,JSONArray route,JSONArray steps,int index,long sample,float accuracy,String identity)throws Exception{Location fix=new Location("synthetic");fix.setLatitude(0);fix.setLongitude(index*.0001);fix.setTime(sample);fix.setAccuracy(accuracy);Method m=MainActivity.class.getDeclaredMethod("buildRouteHudMetrics",Location.class,String.class,String.class,float.class,float.class,String.class);m.setAccessible(true);return (JSONObject)m.invoke(owner,fix,route.toString(),steps.toString(),1112f,600f,identity);}
 static JSONObject display(JSONObject packet)throws Exception{Method m=com.example.rokidkeyboardbridge.MainActivity.class.getClassLoader().loadClass("com.example.rokidkeyboardbridge.JourneyHud").getDeclaredMethod("apply",JSONObject.class,boolean.class);m.setAccessible(true);return (JSONObject)m.invoke(null,packet,false);}
 public static JSONObject run(Context c)throws Exception{cases=new JSONArray();JSONArray route=new JSONArray(),steps=new JSONArray();for(int i=0;i<=100;i++)route.put(new JSONArray().put(0).put(i*.0001));for(double p:new double[]{.2,.5,.8})steps.put(new JSONObject().put("progress",p).put("type","google").put("instruction",p==.5?"左折":"右折").put("distance",300).put("duration",100));
 long now=System.currentTimeMillis(),sample=now-20000;
 for(String travel:new String[]{"walking","bicycling","driving"}){mode=travel;MainActivity owner=ReliabilityChecks.owner(c);String identity=travel+"|trip1";
 check("provider request mode",RoutesRequestPolicy.mode(travel).equals(travel.equals("walking")?"WALK":travel.equals("bicycling")?"BICYCLE":"DRIVE"));
 JSONObject start=hud(owner,route,steps,0,sample,5,identity);check("first turn and distance",start.optString("instruction").equals("右折")&&!start.optString("nextDistance").isEmpty());
 JSONObject passed=hud(owner,route,steps,25,sample+2000,5,identity);check("advance after passed turn",passed.optString("instruction").equals("左折"));
 JSONObject backward=hud(owner,route,steps,18,sample+4000,5,identity);check("GPS back-jump does not revive passed turn",backward.optString("instruction").equals("左折"));
 JSONObject forward=hud(owner,route,steps,60,sample+6000,5,identity);check("next turn",forward.optString("instruction").equals("右折"));
 JSONObject noisy=hud(owner,route,steps,99,sample+8000,80,identity);check("poor GPS does not skip remaining turn",noisy.optString("instruction").equals("右折"));
 JSONObject changed=hud(owner,route,steps,0,sample+10000,5,travel+"|trip2");check("new route resets progress",changed.optString("instruction").equals("右折"));
 JSONObject j=new JSONObject().put("version",1).put("id",identity).put("requestedMode",travel).put("finalDestination","synthetic final").put("wholeRoute",route).put("positionConfirmed",false);
 JSONObject shown=display(new JSONObject().put("journey",j).put("instruction","右折").put("routeReady",true).put("route",route));check("glasses retains whole geometry while GPS selects a step",shown.getJSONArray("route").length()==101&&shown.optBoolean("routeReady"));
 check("arrival at slow destination",NavigationArrivalPolicy.nearFinalPoint(now,now,5,0,now-60000,10));check("passing destination at speed is not arrival",!NavigationArrivalPolicy.nearFinalPoint(now,now,5,10,now-60000,10));check("stale GPS is not arrival",!NavigationArrivalPolicy.nearFinalPoint(now,now-16000,5,0,now-60000,10));
 NavigationDeviation deviation=new NavigationDeviation();double off=travel.equals("walking")?100:travel.equals("bicycling")?150:300;check("single deviation fix does not reroute",!deviation.observe(identity,travel,sample,sample,5,1,off));check("second fix waits for duration",!deviation.observe(identity,travel,sample+4000,sample+4000,5,1,off));check("sustained deviation reroutes",deviation.observe(identity,travel,sample+8000,sample+8000,5,1,off));
 com.example.rokidkeyboardbridge.NavigationTurnCue cue=new com.example.rokidkeyboardbridge.NavigationTurnCue();cue.configure(travel,1);String spoken=cue.update(identity,"右折",travel.equals("bicycling")?"200 m":"100 m",now,now,5,!travel.equals("driving"),true);check("spoken-turn scope",travel.equals("driving")?spoken.isEmpty():!spoken.isEmpty());
 }
 mode="transit";check("provider request mode",RoutesRequestPolicy.mode(mode).equals("TRANSIT"));
 JSONObject ride=MultimodalJourneyTest.ride("synthetic A","synthetic B",0,0.002,0,0.008).put("polyline",new JSONObject().put("encodedPolyline",GooglePolyline.encode(Arrays.asList(new double[][]{{0,.002},{0,.005},{0,.008}})))).put("staticDuration","300s").put("distanceMeters",600);
 JSONObject selected=MultimodalJourneyTest.route(ride).put("polyline",ride.getJSONObject("polyline"));
 MultimodalJourney trip=new MultimodalJourney("synthetic final",new double[]{0,.01},"bicycling","walking");trip.stations(selected);trip.ready=true;check("cycle first mile retained",trip.mode().equals("bicycling"));check("station proximity asks arrival not boarding",trip.geofence(0,.002,5,now,now).equals("arrive"));check("arrival at station does not auto board",trip.phase==MultimodalJourney.Phase.FIRST_MILE);check("explicit boarding",trip.advance("board")&&trip.phase==MultimodalJourney.Phase.TRANSIT_LEG);trip.ready=true;JSONObject train=trip.fetchPhase(0,0,(a,b,x,y,m)->{throw new AssertionError("Selected transit must not trigger another provider request");});check("selected transit preserved",train.getJSONArray("legs").getJSONObject(0).getJSONArray("steps").getJSONObject(0).optString("travelMode").equals("TRANSIT"));check("no backwards phase change",!trip.advance("arrive"));check("explicit alighting",trip.advance("alight")&&trip.mode().equals("walking"));check("no second alight",!trip.advance("alight"));
 check("intermediate station is not final arrival",!NavigationArrivalPolicy.destinationArrivalMessage("synthetic B駅に到着"));

 for(String vehicle:new String[]{"RAIL","BUS"}){mode="transit:"+vehicle;JSONObject j=NavigationAssistanceChecks.journey("synthetic-"+vehicle);j.getJSONObject("currentLeg").getJSONObject("transitDetails").put("transitLine",new JSONObject().put("vehicle",new JSONObject().put("type",vehicle)));com.example.rokidkeyboardbridge.NavigationTransitCue cue=new com.example.rokidkeyboardbridge.NavigationTransitCue();
 check("first proximity fix waits",cue.update(j,"TRANSIT_LEG",35.005,139,10,sample,sample).isEmpty());check("sustained proximity announces planned stop",cue.update(j,"TRANSIT_LEG",35.005,139,10,sample+4000,sample+4000).contains("合成降車駅"));check("near stop prepares alighting",cue.update(j,"TRANSIT_LEG",35.001,139,10,sample+8000,sample+8000).contains("準備"));check("repeated fix does not repeat cue",cue.update(j,"TRANSIT_LEG",35.001,139,10,sample+8000,sample+9000).isEmpty());check("boarding is not alighting",cue.update(j,"BOARDING",35.001,139,10,sample+10000,sample+10000).isEmpty());check("GPS stale suppresses cue",cue.update(j,"TRANSIT_LEG",35.001,139,10,sample,sample+31000).isEmpty());
 }
 int failed=0;for(int i=0;i<cases.length();i++)if(!cases.getJSONObject(i).getBoolean("pass"))failed++;
 return new JSONObject().put("cases",cases).put("passed",cases.length()-failed).put("failed",failed).put("scope","synthetic GPS traces, actual phone HUD method and glasses formatter; no network, no mock GPS injection, no live navigation start");}
}
